const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const windhoekPoint = ee.Geometry.Point(17.0836, -22.5594);
    const aoi = windhoekPoint.buffer(10000); // 10km buffer
    const feb2021Start = '2021-02-01';
    const feb2021End = '2021-03-01';
    const baselineStart = '2010-01-01';
    const baselineEnd = '2020-12-31';

    // 2. Data Acquisition & Pre-processing Functions
    // Function to mask clouds, shadows, etc., using the QA_PIXEL band of Landsat C2
    function maskL8sr(image) {
        const qa = image.select('QA_PIXEL');
        const dilatedCloud = (1 << 1);
        const cirrus = (1 << 2);
        const cloud = (1 << 3);
        const cloudShadow = (1 << 4);
        const mask = qa.bitwiseAnd(dilatedCloud).eq(0)
            .and(qa.bitwiseAnd(cirrus).eq(0))
            .and(qa.bitwiseAnd(cloud).eq(0))
            .and(qa.bitwiseAnd(cloudShadow).eq(0));
        return image.updateMask(mask).select(['SR_B4', 'SR_B5']).multiply(0.0000275).add(-0.2);
    }

    // NDVI calculation function
    function calculateNDVI(image) {
        return image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
    }

    // 3. Processing for 2021
    const l8Collection2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(aoi)
        .filterDate(feb2021Start, feb2021End);

    let ndvi2021_val = null;
    let count2021 = 0;

    const count2021_raw = l8Collection2021.size().getInfo();
    if (count2021_raw > 0) {
        const image2021 = l8Collection2021.map(maskL8sr).map(calculateNDVI).median();
        const stats2021 = image2021.reduceRegion({
            reducer: ee.Reducer.mean().combine({
              reducer2: ee.Reducer.count(),
              sharedInputs: true
            }),
            geometry: aoi,
            scale: 1000,
            maxPixels: 1e9
        });

        const statsData2021 = stats2021.getInfo();
        if (statsData2021 && statsData2021.NDVI_mean !== null) {
            ndvi2021_val = statsData2021.NDVI_mean;
            count2021 = statsData2021.NDVI_count;
        }
    }
    console.log(`2021 Initial Images: ${count2021_raw}`);

    // 4. Processing for Baseline (2010-2020)
    // Harmonize band names across Landsat 5, 7, 8
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').select(['SR_B4', 'SR_B5', 'QA_PIXEL']);
    const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').select(['SR_B3', 'SR_B4', 'QA_PIXEL'], ['SR_B4', 'SR_B5', 'QA_PIXEL']);
    const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').select(['SR_B3', 'SR_B4', 'QA_PIXEL'], ['SR_B4', 'SR_B5', 'QA_PIXEL']);

    const mergedCollection = ee.ImageCollection(l5.merge(l7).merge(l8));

    const baselineCollection = mergedCollection
        .filterBounds(aoi)
        .filterDate(baselineStart, baselineEnd)
        .filter(ee.Filter.calendarRange(2, 2, 'month'));

    let baseline_ndvi_val = null;
    let count_baseline = 0;

    const count_baseline_raw = baselineCollection.size().getInfo();
    if (count_baseline_raw > 0) {
        const baselineImage = baselineCollection.map(maskL8sr).map(calculateNDVI).median();
        const statsBaseline = baselineImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
              reducer2: ee.Reducer.count(),
              sharedInputs: true
            }),
            geometry: aoi,
            scale: 1000,
            maxPixels: 1e9
        });

        const statsDataBase = statsBaseline.getInfo();
        if (statsDataBase && statsDataBase.NDVI_mean !== null) {
            baseline_ndvi_val = statsDataBase.NDVI_mean;
            count_baseline = statsDataBase.NDVI_count;
        }
    }
    console.log(`Baseline (2010-2020) Initial Images: ${count_baseline_raw}`);

    // 5. Validation & Final Answer
    if (count2021_raw === 0 || count_baseline_raw === 0) {
        console.log('Evidence: No images found for one or both periods.');
        console.log('A');
        return;
    }

    if (count2021 === 0 || count_baseline === 0) {
        console.log('Evidence: No valid pixels after cloud masking for one or both periods.');
        console.log('C2');
        return;
    }

    if (ndvi2021_val === null || baseline_ndvi_val === null) {
        console.log('Evidence: Calculation failed, result is null.');
        console.log('C3');
        return;
    }

    console.log(`Feb 2021 Mean NDVI: ${ndvi2021_val.toFixed(4)} (Pixels: ${count2021})`);
    console.log(`Feb 2010-2020 Mean NDVI: ${baseline_ndvi_val.toFixed(4)} (Pixels: ${count_baseline})`);

    if (ndvi2021_val > baseline_ndvi_val) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
